<?php
namespace App\Core;
final class DeployManager
{
    private const TABLES=['goldensite_pages','goldensite_posts','goldensite_menus'];
    private const SETTINGS=['site_title','site_description','active_theme','theme_profiles','site_typography','site_language','custom_ai_frontend','use_ai_frontend','builder_content_policy'];
    public static function capture(\PDO $db): array { $snapshot=['format'=>1,'tables'=>[],'settings'=>[]]; foreach (self::TABLES as $table) $snapshot['tables'][$table]=$db->query('SELECT * FROM `'.$table.'` ORDER BY id')->fetchAll(\PDO::FETCH_ASSOC); $stmt=$db->prepare('SELECT setting_key,setting_value FROM settings WHERE setting_key IN ('.implode(',',array_fill(0,count(self::SETTINGS),'?')).')'); $stmt->execute(self::SETTINGS); $snapshot['settings']=$stmt->fetchAll(\PDO::FETCH_KEY_PAIR); return $snapshot; }
    public static function encode(array $snapshot): string { $json=json_encode($snapshot,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE); if (strlen($json)>8388608) throw new \InvalidArgumentException('La versión de contenido supera 8 MB.'); return $json; }
    public static function checksum(string $json): string { return hash_hmac('sha256',$json,KeyStore::vault()); }
    public static function load(array $release): array { if (!hash_equals(self::checksum($release['snapshot_json']),$release['checksum'])) throw new \RuntimeException('La integridad de la versión no es válida.'); $data=json_decode($release['snapshot_json'],true,64,JSON_THROW_ON_ERROR); if (($data['format']??0)!==1||array_keys($data['tables']??[])!==self::TABLES||array_diff(array_keys($data['settings']??[]),self::SETTINGS)) throw new \RuntimeException('Formato de versión inválido.'); return $data; }
    public static function stage(string $label): int { $db=Database::getInstance()->getConnection(); $db->beginTransaction(); try { $json=self::encode(self::capture($db)); $db->prepare("INSERT INTO goldensite_deploy_releases (label,snapshot_json,checksum,state,created_by) VALUES (?,?,?,'staging',?)")->execute([$label,$json,self::checksum($json),Auth::id()]); $id=(int)$db->lastInsertId(); $db->commit(); return $id; } catch (\Throwable $e) { if ($db->inTransaction()) $db->rollBack(); throw $e; } }
    public static function edit(int $id,array $input,string $expected): void { $db=Database::getInstance()->getConnection(); $db->beginTransaction(); try {
        $stmt=$db->prepare('SELECT * FROM goldensite_deploy_releases WHERE id=? FOR UPDATE'); $stmt->execute([$id]); $r=$stmt->fetch(\PDO::FETCH_ASSOC); if (!$r||$r['state']!=='staging'||!hash_equals($r['checksum'],$expected)) throw new \InvalidArgumentException('La versión cambió o ya no admite edición.');
        $data=self::load($r); $found=false; foreach ($data['tables']['goldensite_pages'] as &$page) if ((int)$page['id']===(int)($input['page_id']??0)) { $title=ConsoleView::field($input,'page_title',255); $content=ConsoleView::field($input,'content',1048576); if (!IdentityAccess::superuser()) $content=CmsMigration::clean($content); if (!$title) throw new \InvalidArgumentException('Escribe un título.'); $page['title']=$title; $page['content']=$content; $found=true; break; } unset($page); if (!$found) throw new \InvalidArgumentException('Página inexistente en esta versión.');
        $json=self::encode($data); $db->prepare('UPDATE goldensite_deploy_releases SET snapshot_json=?,checksum=? WHERE id=?')->execute([$json,self::checksum($json),$id]); $db->commit();
    } catch (\Throwable $e) { if ($db->inTransaction()) $db->rollBack(); throw $e; } }
    public static function publish(int $id,string $expected): void {
        $db=Database::getInstance()->getConnection(); $db->beginTransaction(); try {
            // A shared row serializes simultaneous publish/rollback operations.
            $db->exec("INSERT IGNORE INTO settings (setting_key,setting_value) VALUES ('deploy_generation','0')"); $generation=(int)$db->query("SELECT setting_value FROM settings WHERE setting_key='deploy_generation' FOR UPDATE")->fetchColumn();
            $stmt=$db->prepare('SELECT * FROM goldensite_deploy_releases WHERE id=? FOR UPDATE'); $stmt->execute([$id]); $release=$stmt->fetch(\PDO::FETCH_ASSOC); if (!$release||!hash_equals($release['checksum'],$expected)||!in_array($release['state'],['staging','archived','backup'],true)) throw new \InvalidArgumentException('La versión no está disponible para esta operación.');
            $data=self::load($release); $backup=self::encode(self::capture($db)); $db->prepare("INSERT INTO goldensite_deploy_releases (label,snapshot_json,checksum,state,created_by) VALUES (?,?,?,'backup',?)")->execute(['Respaldo anterior a #'.$id,$backup,self::checksum($backup),Auth::id()]);
            foreach (self::TABLES as $table) { $columns=$db->query('SHOW COLUMNS FROM `'.$table.'`')->fetchAll(\PDO::FETCH_COLUMN); $db->exec('DELETE FROM `'.$table.'`'); foreach ($data['tables'][$table] as $row) { if (!is_array($row)||array_diff(array_keys($row),$columns)) throw new \RuntimeException('La estructura de contenido cambió; vuelve a preparar una versión.'); $keys=array_keys($row); $quoted=implode(',',array_map(static fn($k)=>'`'.$k.'`',$keys)); $db->prepare('INSERT INTO `'.$table.'` ('.$quoted.') VALUES ('.implode(',',array_fill(0,count($keys),'?')).')')->execute(array_values($row)); } }
            $set=$db->prepare('INSERT INTO settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)'); foreach (self::SETTINGS as $key) { if (array_key_exists($key,$data['settings'])) $set->execute([$key,$data['settings'][$key]]); else $db->prepare('DELETE FROM settings WHERE setting_key=?')->execute([$key]); }
            $db->exec("UPDATE goldensite_deploy_releases SET state='archived' WHERE state='production'"); $db->prepare("UPDATE goldensite_deploy_releases SET state='production',published_at=NOW() WHERE id=?")->execute([$id]); $set->execute(['deploy_generation',(string)($generation+1)]); $db->commit(); Settings::reset(); CacheStore::clear();
        } catch (\Throwable $e) { if ($db->inTransaction()) $db->rollBack(); throw $e; }
    }
}
